# Import necessary libraries for creating an AI API service
from flask import Flask, request, jsonify
import openai

app = Flask(__name__)

# Initialize OpenAI's GPT-3 model
openai.api_key = 'your-api-key'

@app.route('/api/v1/generate', methods=['POST'])
def generate_text():
    """
    This function receives a POST request containing a prompt and returns generated text.
    """
    data = request.get_json()  # Get the JSON data from the POST request
    prompt = data['prompt']  # Extract the 'prompt' key from the data

    try:
        response = openai.Completion.create(
            engine="text-davinci-003",  # Specify the model to use
            prompt=prompt,  # The input text or prompt for the AI to generate a response
            max_tokens=150  # Maximum number of tokens in the generated response
        )
        return jsonify({'generated_text': response.choices[0].text.strip()})  # Return the generated text
    except Exception as e:
        return jsonify({'error': str(e)}), 400  # Return an error message if something goes wrong

if __name__ == '__main__':
    app.run(debug=True)  # Run the Flask application in debug mode

# This code sets up a basic API service that uses OpenAI's GPT-3 model to generate text based on a given prompt.
